const items = $input.all();

// Get persistent workflow data
const staticData = $getWorkflowStaticData('global');

// Initialize the counter if it doesn't exist
if (typeof staticData.lastId !== 'number') {
  staticData.lastId = 0;
}

return items.map((item) => {
  const data = item.json;

  // Generate a new ID automatically
  staticData.lastId += 1;
  const newId = staticData.lastId;

  // Get the AI response from common possible fields
  let response =
    data.output ??
    data.text ??
    data.response ??
    data.content ??
    data.message ??
    "";

  // If the AI returned an object instead of text
  if (typeof response !== "string") {
    response = JSON.stringify(response);
  }

  // Try to extract JSON
  let parsed = null;

  try {
    parsed = JSON.parse(response);
  } catch (error) {
    const jsonMatch = response.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
      try {
        parsed = JSON.parse(jsonMatch[0]);
      } catch (e) {
        parsed = null;
      }
    }
  }

  // If AI returned valid structured JSON
  if (parsed && typeof parsed === "object") {
    return {
      json: {
        id: newId,

        idea: parsed.idea ?? data.idea ?? null,

        score: Number(parsed.score ?? 0),

        Review:
          parsed.Review ??
          parsed.review ??
          "",

        Reason:
          parsed.Reason ??
          parsed.reason ??
          "",

        Verdict:
          parsed.Verdict ??
          parsed.verdict ??
          "",

        EmailSubject:
          parsed.EmailSubject ??
          parsed.emailSubject ??
          "",

        ContentTitle:
          parsed.ContentTitle ??
          parsed.contentTitle ??
          ""
      }
    };
  }

  // Fallback: extract fields from normal AI text

  const scoreMatch = response.match(
    /(?:التقييم|score)\s*[:：]?\s*(\d+(?:\.\d+)?)\s*\/?\s*10/i
  );

  const verdictMatch = response.match(
    /(?:الحكم|verdict)\s*[:：]?\s*(.+)/i
  );

  const reasonMatch = response.match(
    /(?:السبب|reason)\s*[:：]?\s*([\s\S]*?)(?=\n(?:الحكم|verdict)\s*[:：]?|$)/i
  );

  const emailSubjectMatch = response.match(
    /(?:EmailSubject|emailSubject)\s*[:：]?\s*(.+)/i
  );

  const contentTitleMatch = response.match(
    /(?:ContentTitle|contentTitle)\s*[:：]?\s*(.+)/i
  );

  return {
    json: {
      id: newId,

      idea: data.idea ?? null,

      score: scoreMatch
        ? Number(scoreMatch[1])
        : 0,

      Review: response.trim(),

      Reason: reasonMatch
        ? reasonMatch[1].trim()
        : "",

      Verdict: verdictMatch
        ? verdictMatch[1].trim()
        : "",

      EmailSubject: emailSubjectMatch
        ? emailSubjectMatch[1].trim()
        : "",

      ContentTitle: contentTitleMatch
        ? contentTitleMatch[1].trim()
        : ""
    }
  };
});

