=<!DOCTYPE html>
<html lang="ar" dir="rtl">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <style>
    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: 0;
      background-color: #f3f4f6;
      font-family: Arial, Helvetica, sans-serif;
      color: #111827;
      direction: rtl;
    }

    .wrapper {
      width: 100%;
      padding: 40px 15px;
    }

    .container {
      max-width: 680px;
      margin: 0 auto;
      background-color: #ffffff;
      border-radius: 18px;
      overflow: hidden;
      border: 1px solid #e5e7eb;
    }

    /* Header */

    .header {
      background-color: #111827;
      padding: 30px;
      text-align: right;
    }

    .brand {
      margin: 0;
      color: #ffffff;
      font-size: 24px;
      font-weight: 700;
    }

    .subtitle {
      margin: 8px 0 0;
      color: #9ca3af;
      font-size: 14px;
      line-height: 1.7;
    }

    /* Main */

    .content {
      padding: 32px;
    }

    .section-label {
      display: block;
      margin-bottom: 8px;
      color: #6b7280;
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
    }

    .content-title {
      margin: 0 0 25px;
      color: #111827;
      font-size: 24px;
      line-height: 1.5;
      font-weight: 700;
    }

    /* Score */

    .score-box {
      display: table;
      width: 100%;
      margin-bottom: 25px;
      background-color: #f9fafb;
      border: 1px solid #e5e7eb;
      border-radius: 12px;
    }

    .score-cell {
      display: table-cell;
      width: 50%;
      padding: 18px;
      vertical-align: middle;
    }

    .score-cell:first-child {
      border-left: 1px solid #e5e7eb;
    }

    .score-label {
      display: block;
      color: #6b7280;
      font-size: 12px;
      margin-bottom: 6px;
    }

    .score {
      color: #16a34a;
      font-size: 28px;
      font-weight: 700;
    }

    .verdict {
      display: inline-block;
      padding: 7px 12px;
      border-radius: 7px;
      background-color: #dcfce7;
      color: #166534;
      font-size: 13px;
      font-weight: 700;
    }

    /* Idea */

    .idea-box {
      margin-bottom: 22px;
      padding: 20px;
      background-color: #f9fafb;
      border-right: 4px solid #111827;
      border-radius: 10px;
    }

    .idea {
      margin: 0;
      color: #374151;
      font-size: 15px;
      line-height: 1.8;
    }

    /* Sections */

    .section {
      margin-bottom: 22px;
    }

    .section-title {
      margin: 0 0 8px;
      color: #111827;
      font-size: 14px;
      font-weight: 700;
    }

    .section-text {
      margin: 0;
      color: #4b5563;
      font-size: 14px;
      line-height: 1.8;
    }

    /* ID */

    .meta {
      margin-top: 25px;
      padding-top: 18px;
      border-top: 1px solid #e5e7eb;
      color: #9ca3af;
      font-size: 12px;
    }

    /* Footer */

    .footer {
      padding: 20px 30px;
      background-color: #f9fafb;
      border-top: 1px solid #e5e7eb;
      text-align: center;
    }

    .footer-text {
      margin: 0;
      color: #9ca3af;
      font-size: 12px;
      line-height: 1.7;
    }

    /* Mobile */

    @media only screen and (max-width: 600px) {

      .wrapper {
        padding: 0;
      }

      .container {
        width: 100%;
        border-radius: 0;
        border: none;
      }

      .header {
        padding: 25px 20px;
      }

      .content {
        padding: 25px 20px;
      }

      .content-title {
        font-size: 21px;
      }

      .score-cell {
        padding: 15px;
      }
    }
  </style>
</head>

<body>

  <div class="wrapper">

    <div class="container">

      <!-- Header -->

      <div class="header">

        <h1 class="brand">
          GOAT Learner
        </h1>

        <p class="subtitle">
          Content Idea Review
        </p>

      </div>


      <!-- Content -->

      <div class="content">

        <!-- Content Title -->

        <span class="section-label">
          عنوان الفيديو المقترح
        </span>

        <h2 class="content-title">
          {{ $('If').item.json.ContentTitle }}
        </h2>


        <!-- Score -->

        <div class="score-box">

          <div class="score-cell">

            <span class="score-label">
              التقييم
            </span>

            <span class="score">
              {{ $json.Score }}/10
            </span>

          </div>


          <div class="score-cell">

            <span class="score-label">
              الحكم
            </span>

            <span class="verdict">
              {{ $json.Verdict }}
            </span>

          </div>

        </div>


        <!-- Idea -->

        <div class="section">

          <h3 class="section-title">
            💡 الفكرة
          </h3>

          <div class="idea-box">

            <p class="idea">
              {{ $json.Ideas }}
            </p>

          </div>

        </div>


        <!-- Review -->

        <div class="section">

          <h3 class="section-title">
            📊 المراجعة
          </h3>

          <p class="section-text">
            {{ $json.Review }}
          </p>

        </div>


        <!-- Reason -->

        <div class="section">

          <h3 class="section-title">
            🔎 سبب التقييم
          </h3>

          <p class="section-text">
            {{ $json.Reason }}
          </p>

        </div>


        <!-- Meta -->

        <div class="meta">

          فكرة رقم:
          <strong>
            {{ $json.ID }}
          </strong>

        </div>

      </div>


      <!-- Footer -->

      <div class="footer">

        <p class="footer-text">
          تم تقييم هذه الفكرة تلقائيًا وفق معايير محتوى GOAT Learner.
          <br>
          الأفكار ذات التقييم 8/10 أو أعلى تستحق المراجعة.
        </p>

      </div>

    </div>

  </div>

</body>

</html>
